<?php require_once 'config.php';if(!user())go('login.php');$st=$pdo->prepare("SELECT * FROM orders WHERE user_id=? ORDER BY id DESC");$st->execute([user()['id']]);$rows=$st->fetchAll();$title='My orders';include 'header.php';?><h1>My orders</h1><div class="panel"><table class="table"><tr><th>Order</th><th>Date</th><th>Total</th><th>Status</th></tr><?php foreach($rows as $o): ?><tr><td>#<?= $o['id'] ?></td><td><?= h($o['created_at']) ?></td><td><?= money($o['total']) ?></td><td><?= h($o['status']) ?></td></tr><?php endforeach; ?></table><?php if(!$rows)echo 'No orders yet.';?></div><?php include 'footer.php'; ?>
